function toColumns(headers: string[], rows: any[][]): Record<string, any[]> {
  const out: Record<string, any[]> = {};
  for (const h of headers) out[h] = [];
  for (const row of rows) {
    row.forEach((v, j) => out[headers[j]].push(v));
  }
  return out;
}

